import {business} from './config.js';
import {money} from './store.js';

const flowEsc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const flowStates={pending:'Awaiting owner approval',approved:'Approved · ready to pay',rejected:'Request declined',payment_reported:'Payment reference submitted · verification pending',paid:'Payment verified by owner'};
let flowKeys={};try{flowKeys=JSON.parse(localStorage.getItem('sbb-orders')||'{}');}catch{}
if(!flowKeys||typeof flowKeys!=='object'||Array.isArray(flowKeys))flowKeys={};
flowKeys=Object.fromEntries(Object.entries(flowKeys).filter(([id,key])=>/^SBB-[A-F0-9]{12}$/.test(id)&&/^[a-f0-9]{64}$/.test(key)));
let flowTimer,flowGeneration=0,flowRoute='',flowFingerprint='',flowBusy=false,flowDraft=null;
const flowSave=()=>{try{localStorage.setItem('sbb-orders',JSON.stringify(flowKeys));return true;}catch{return false;}};
async function flowApi(url,{method='GET',body,token}={}){
 if(!/^https?:$/.test(location.protocol))throw new Error('Order approval requires the running website server. Open http://localhost:4173/.');
 let response;try{response=await fetch(url,{method,headers:{...(body?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{})},body:body?JSON.stringify(body):undefined,credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(15000)});}catch{throw new Error('Cannot reach the order server. Your selection is preserved. Please try again.');}
 let data;try{data=await response.json();}catch{throw new Error('The order server is unavailable. Please try again.');}
 if(!response.ok){const error=new Error(data.error||'Please try again.');error.status=response.status;throw error;}return data;
}
export async function placeOrder(details,items){
 const fingerprint=JSON.stringify({details,items});if(!flowDraft||flowDraft.fingerprint!==fingerprint){let stored;try{stored=JSON.parse(sessionStorage.getItem('sbb-order-draft')||'null');}catch{}flowDraft=stored?.fingerprint===fingerprint?stored:{fingerprint,key:[...crypto.getRandomValues(new Uint8Array(32))].map(n=>n.toString(16).padStart(2,'0')).join('')};try{sessionStorage.setItem('sbb-order-draft',JSON.stringify(flowDraft));}catch{}}
 const {order}=await flowApi('/api/orders',{method:'POST',body:{details,items,clientKey:flowDraft.key}});flowKeys[order.id]=flowDraft.key;flowSave();try{sessionStorage.removeItem('sbb-order-draft');}catch{}flowDraft=null;return order;
}
export function orderPage(kind){const text={orders:['YOUR ORDER, AT EVERY STEP','Your order <em>updates.</em>','Owner approval comes first. Your payment button appears once the final total is confirmed.'],owner:['OWNER ACCESS · 9591457484','The workshop <em>inbox.</em>','Review requests, confirm the final total and approve payment.'],payment:['DIRECT TO THE WORKSHOP','Confirm, then <em>pay.</em>','Payment opens only for an order approved by the workshop.']}[kind];return `<section class="container section order-page ${kind==='owner'?'owner-page':''}"><span class="eyebrow">${text[0]}</span><h1>${text[1]}</h1><p class="intro">${text[2]}</p><div id="order-feedback" role="status" tabindex="-1"></div><div id="order-flow" aria-live="polite"><p>Loading your ${kind==='owner'?'inbox':'order'}…</p></div></section>`;}
const flowItems=o=>`<ul class="order-lines">${o.items.map(i=>`<li><span>${flowEsc(i.name)} <small lang="kn">${flowEsc(i.nameKn)}</small><small>${flowEsc(i.size)}${i.lengthFeet?' · '+i.lengthFeet+' ft':''} · Qty ${i.quantity}${i.unit==='pair'?' pairs':''}</small></span></li>`).join('')}</ul>`;
const flowSummary=o=>`<div class="order-heading"><div><span class="eyebrow">${flowEsc(o.id)}</span><h2>${flowStates[o.status]||'Order update'}</h2></div><span class="order-date">${new Date(o.createdAt).toLocaleDateString('en-IN')}</span></div>${flowItems(o)}${o.approvedTotal!==null?`<p class="approved-total">Final total <strong>${money(o.approvedTotal/100)}</strong><small>Includes the delivery and specifications agreed with the workshop.</small></p>`:`<p class="small muted">Product estimate: ${money(o.estimate.low)}${o.estimate.low!==o.estimate.high?'–'+money(o.estimate.high):''}. Final total, units, specifications and delivery require owner confirmation.</p>`}${o.ownerNote?`<div class="owner-note"><strong>Workshop note</strong><p>${flowEsc(o.ownerNote)}</p></div>`:''}`;
const flowTrackingUrl=id=>`${location.origin}/#/orders?order=${encodeURIComponent(id)}&access=${flowKeys[id]}`;
function flowCustomerCard(o){const ownerUrl=`${location.origin}/owner?order=${o.id}`;const message=`New order request ${o.id}. Please review availability, specifications and final total in the owner inbox: ${ownerUrl}`;const notice=o.notification?.status==='accepted'?'WhatsApp alert submitted to the provider. Delivery has not been verified.':o.notification?.status==='failed'?'Automatic WhatsApp alert failed. Please notify the owner using the button below.':'Automatic WhatsApp alerts are not connected. Use the button below to notify the owner.';
 return `<article class="order-card">${flowSummary(o)}${o.status==='pending'?`<div class="request-notice"><strong>Your request is saved. Approval is pending.</strong><p>${notice}</p></div><a class="button button-outline" href="https://wa.me/919591457484?text=${encodeURIComponent(message)}" target="_blank" rel="noopener noreferrer">Notify owner on WhatsApp ↗</a>`:''}${o.status==='approved'?`<div class="request-notice"><strong>The owner has approved your order.</strong><p>Check the final total and workshop note, then choose Confirm & pay to view the QR.</p></div><a class="button" href="/payment?order=${o.id}">Confirm &amp; pay ${money(o.approvedTotal/100)} →</a>`:''}${o.status==='payment_reported'?`<div class="request-notice"><strong>Your payment is awaiting the owner’s check.</strong><p>Reference: ${flowEsc(o.paymentReference)}. This is not proof of payment. Avoid paying twice.</p></div><a class="text-link" href="/payment?order=${o.id}">Review payment details →</a>`:''}${o.status==='paid'?'<div class="request-notice"><strong>Payment receipt confirmed by the owner.</strong><p>Contact the workshop for delivery updates.</p></div>':''}<details class="tracking-details"><summary>Your private tracking link</summary><p>Saved on this browser. Keep this link private; open it on another device to view this order there.</p><button type="button" class="button button-outline" data-copy-order="${o.id}">Copy private tracking link</button><input class="tracking-link" aria-label="Private tracking link for ${o.id}" readonly value="${flowEsc(flowTrackingUrl(o.id))}"></details></article>`;
}
async function flowLoadCustomers(generation){
 const root=document.querySelector('#order-flow');if(!root)return;
 if(!Object.keys(flowKeys).length){root.innerHTML='<div class="request-notice"><h2>No saved orders yet.</h2><p>Submit your bag for owner approval. If you ordered on another device, open the private tracking link saved on that device.</p><a class="button" href="/shop">Explore the collection →</a></div>';return;}
 const results=await Promise.all(Object.keys(flowKeys).reverse().slice(0,30).map(async id=>{try{return {order:(await flowApi('/api/orders/'+id,{token:flowKeys[id]})).order};}catch(e){return {id,error:e.message};}}));if(generation!==flowGeneration)return;
 const fingerprint=JSON.stringify(results);if(fingerprint===flowFingerprint)return;flowFingerprint=fingerprint;root.innerHTML=`<div class="order-toolbar"><p>Updates refresh every 15 seconds while this page is open.</p><button class="button button-outline" data-refresh-orders>Refresh status</button></div>${results.map(r=>r.order?flowCustomerCard(r.order):`<div class="request-notice"><strong>${flowEsc(r.id)}</strong><p>${flowEsc(r.error)}</p></div>`).join('')}`;
}
function flowLogin(mfaRequired=false){return `<form id="owner-login-form" class="form-panel owner-login"><h2>Sign in as owner</h2><p>For Sri Balaji Bamboo Works · 9591457484. A phone number alone does not grant access.</p><label for="owner-password">Owner password</label><input id="owner-password" name="password" type="password" autocomplete="current-password" required maxlength="256"><label for="owner-otp">Authenticator code${mfaRequired?'':' (if configured)'}</label><input id="owner-otp" name="otp" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" ${mfaRequired?'required':''}><button class="button" type="submit">Open owner inbox →</button><p class="small muted">For this local installation, your initial password is in the private owner-access.txt file on the server. Never share it with customers.</p></form>`;}
function flowOwnerCard(o,highlight){return `<article class="order-card${highlight===o.id?' order-highlight':''}">${flowSummary(o)}<details class="owner-customer"><summary>Customer &amp; delivery details</summary><dl class="payment-details">${Object.entries(o.details).filter(([,v])=>v).map(([k,v])=>`<div><dt>${flowEsc(k)}</dt><dd>${flowEsc(v)}</dd></div>`).join('')}</dl></details>${o.status==='pending'?`<form class="owner-approve-form form-panel" data-order="${o.id}"><h3>Approve this request</h3><label for="total-${o.id}">Final total in ₹, including delivery</label><input id="total-${o.id}" name="total" type="number" inputmode="decimal" step="0.01" min="0.01" max="10000000" required><label for="note-${o.id}">Specifications, delivery and workshop note</label><textarea id="note-${o.id}" name="note" rows="3" maxlength="1500" placeholder="Confirm the selected size, quantity and delivery arrangement."></textarea><label class="approval-check"><input type="checkbox" name="detailsConfirmed" required> I have checked availability, specifications and the final total with delivery.</label><button class="button" type="submit">Approve &amp; unlock payment</button></form><details class="decline-order"><summary>Cannot accept this request?</summary><form class="owner-reject-form" data-order="${o.id}"><label for="decline-${o.id}">Reason for declining</label><textarea id="decline-${o.id}" name="note" required maxlength="1500"></textarea><button class="button button-outline" type="submit">Decline request</button></form></details>`:''}${['approved','payment_reported'].includes(o.status)?`<form class="owner-paid-form form-panel" data-order="${o.id}"><h3>Check payment receipt</h3><p>${o.paymentReference?'Customer reference: '+flowEsc(o.paymentReference):'The customer has not submitted a transaction reference.'} A reference or screenshot alone does not prove receipt.</p><label class="approval-check"><input type="checkbox" name="receiptChecked" required> I have verified ${money(o.approvedTotal/100)} was received in our merchant account for this order.</label><button class="button button-outline" type="submit">Confirm payment received</button></form>`:''}</article>`;}
async function flowLoadOwner(generation,params){const root=document.querySelector('#order-flow');try{const session=await flowApi('/api/owner/session');if(generation!==flowGeneration)return;if(!session.authenticated){root.innerHTML=flowLogin(session.mfaRequired);return;}const {orders}=await flowApi('/api/owner/orders');if(generation!==flowGeneration)return;const pending=orders.filter(o=>o.status==='pending').length;root.innerHTML=`<div class="order-toolbar"><p><strong>${pending} pending</strong> · ${orders.length} total requests</p><div class="request-actions"><button class="button button-outline" data-refresh-orders>Refresh inbox</button><button class="button button-outline" data-owner-logout>Sign out</button></div></div>${orders.length?orders.map(o=>flowOwnerCard(o,params.get('order'))).join(''):'<div class="request-notice"><h2>Your inbox is clear.</h2><p>Customer requests will appear here after submission.</p></div>'}`;}catch(e){if(generation!==flowGeneration)return;if(e.status===401)root.innerHTML=flowLogin();else root.innerHTML=`<div class="request-notice"><p>${flowEsc(e.message)}</p><button class="button" data-refresh-orders>Try again</button></div>`;}}
async function flowLoadPayment(generation,params){const root=document.querySelector('#order-flow');const id=params.get('order');if(!id||!flowKeys[id]){root.innerHTML='<div class="request-notice"><h2>Owner approval comes first.</h2><p>Open My orders and choose Confirm &amp; pay on an approved request. If you used another device, open your private tracking link first.</p><a class="button" href="/orders">My orders →</a></div>';return;}
 try{const {order:o,payment:p}=await flowApi('/api/orders/'+id+'/payment',{token:flowKeys[id]});if(generation!==flowGeneration)return;root.innerHTML=`<div class="payment-layout"><figure class="payment-qr"><img src="${flowEsc(p.qrImage)}" width="848" height="1205" alt="Original merchant UPI QR for Sri Balaji Bamboo Work"><figcaption>Original merchant QR supplied by the workshop.</figcaption><a class="text-link" href="${flowEsc(p.qrImage)}" download="Sri-Balaji-UPI-QR.jpg">Save payment QR ↓</a></figure><div class="payment-instructions"><span class="eyebrow">${flowEsc(o.id)}</span><h2>${o.status==='payment_reported'?'Payment reference received.':'Your approved order.'}</h2><p class="approved-total">Pay exactly <strong>${money(o.approvedTotal/100)}</strong></p>${o.ownerNote?`<p class="owner-note">${flowEsc(o.ownerNote)}</p>`:''}<dl class="payment-details"><div><dt>Merchant name</dt><dd>${flowEsc(p.merchantName)}</dd></div><div><dt>UPI ID</dt><dd>${flowEsc(p.upiId)}</dd></div></dl><ol class="payment-steps"><li>Scan the QR with your UPI app. On the same phone, save the QR and use your app’s image scan option if available.</li><li>Check the recipient and pay only the approved total shown above.</li><li>Enter your UPI transaction reference below. The owner checks actual receipt before marking the order paid.</li></ol>${o.status==='payment_reported'?`<div class="payment-notice"><strong>Verification pending. Avoid paying twice.</strong><p>Submitted reference: ${flowEsc(o.paymentReference)}.</p></div>`:''}<form id="payment-report-form" data-order="${o.id}" class="form-panel"><h3>${o.status==='payment_reported'?'Correct your transaction reference':'Already paid in your UPI app?'}</h3><label for="payment-reference">UPI transaction reference</label><input id="payment-reference" name="reference" minlength="6" maxlength="80" pattern="[A-Za-z0-9 -]{6,80}" value="${flowEsc(o.paymentReference)}" required><button class="button" type="submit">Submit reference for verification</button><p class="small muted">This does not confirm payment. The workshop verifies receipt manually.</p></form><a class="text-link" href="/orders">Back to My orders →</a></div></div>`;}catch(e){if(generation===flowGeneration)root.innerHTML=`<div class="request-notice"><h2>Payment is not available.</h2><p>${flowEsc(e.message)}</p><a class="button" href="/orders">Check order status →</a></div>`;}}
export function mountOrders(route,params){
 clearInterval(flowTimer);flowGeneration++;flowRoute=route;flowFingerprint='';const generation=flowGeneration;
 if(route==='/orders'){const id=params.get('order'),key=params.get('access');if(/^SBB-[A-F0-9]{12}$/.test(id||'')&&/^[a-f0-9]{64}$/.test(key||'')){flowKeys[id]=key;flowSave();history.replaceState(null,'','/orders');}flowLoadCustomers(generation);flowTimer=setInterval(()=>{if(!document.hidden&&!flowBusy)flowLoadCustomers(generation);},15000);}
 if(route==='/owner')flowLoadOwner(generation,params);
 if(route==='/payment')flowLoadPayment(generation,params);
 if(!['/orders','/owner','/payment'].includes(route)&&Object.keys(flowKeys).length){const main=document.querySelector('#main');const banner=document.createElement('aside');banner.className='customer-order-banner container';banner.innerHTML='<span>You have saved order requests.</span><a href="/orders">View My orders →</a>';main.prepend(banner);Promise.all(Object.entries(flowKeys).slice(-10).map(async([id,key])=>{try{return (await flowApi('/api/orders/'+id,{token:key})).order;}catch{return null;}})).then(orders=>{if(generation!==flowGeneration)return;const approved=orders.find(o=>o?.status==='approved');if(approved)banner.innerHTML=`<span>Order ${flowEsc(approved.id)} approved · ${money(approved.approvedTotal/100)}</span><a href="/payment?order=${approved.id}">Confirm &amp; pay →</a>`;});}
}
function flowFeedback(message,error=false){const box=document.querySelector('#order-feedback');if(box){box.className=error?'order-feedback error-summary':'order-feedback request-notice';box.textContent=message;box.focus();}}
export function setupOrderEvents(){
 document.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;
  if(button.hasAttribute('data-refresh-orders')){flowFingerprint='';if(flowRoute==='/owner')flowLoadOwner(flowGeneration,new URLSearchParams(location.search||location.hash.split('?')[1]||''));else flowLoadCustomers(flowGeneration);}
  if(button.hasAttribute('data-owner-logout')){try{await flowApi('/api/owner/logout',{method:'POST',body:{}});flowLoadOwner(flowGeneration,new URLSearchParams());}catch(e){flowFeedback(e.message,true);}}
  if(button.dataset.copyOrder){try{await navigator.clipboard.writeText(flowTrackingUrl(button.dataset.copyOrder));flowFeedback('Private tracking link copied. Keep it safe.');}catch{flowFeedback('Select and copy the private tracking link shown below.');button.parentElement.querySelector('input').select();}}
 });
 document.addEventListener('submit',async event=>{
  const form=event.target;if(!form.matches('#owner-login-form,.owner-approve-form,.owner-reject-form,.owner-paid-form,#payment-report-form'))return;event.preventDefault();if(flowBusy||!form.reportValidity())return;flowBusy=true;const button=form.querySelector('button[type="submit"]');button.disabled=true;const generation=flowGeneration;
  try{const values=Object.fromEntries(new FormData(form));
   if(form.id==='owner-login-form'){await flowApi('/api/owner/login',{method:'POST',body:{password:values.password,otp:values.otp}});form.reset();await flowLoadOwner(generation,new URLSearchParams(location.search||location.hash.split('?')[1]||''));}
   else if(form.id==='payment-report-form'){await flowApi('/api/orders/'+form.dataset.order+'/report',{method:'POST',token:flowKeys[form.dataset.order],body:{reference:values.reference}});location.hash='/orders';}
   else{const action=form.matches('.owner-approve-form')?'approve':form.matches('.owner-reject-form')?'reject':'paid';await flowApi('/api/owner/orders/'+form.dataset.order+'/'+action,{method:'POST',body:{...values,receiptChecked:values.receiptChecked==='on',detailsConfirmed:values.detailsConfirmed==='on'}});await flowLoadOwner(generation,new URLSearchParams(location.search||location.hash.split('?')[1]||''));flowFeedback(action==='approve'?'Order approved. The customer can now confirm and pay.':action==='paid'?'Payment marked received after your merchant-account check.':'Request declined. The customer can see your reason.');}
  }catch(e){if(generation===flowGeneration)flowFeedback(e.message,true);}finally{flowBusy=false;button.disabled=false;}
 });
 window.addEventListener('focus',()=>{if(flowRoute==='/orders'&&!flowBusy)flowLoadCustomers(flowGeneration);});
}
